#include "model.hpp"
namespace pe::civic {
void grant(State&s,const Command&c){auto&p=person(s,c.actor);idle(p);auto& org=institution(s,c.param("organization",100));require(org.office.holder==p.id&&org.office.can_grant,"No office permission to spend treasury");person(s,c.target);require(c.amount<=50,"Grant maximum50");Transaction{}.money(org.id,c.target,c.amount).commit(s);emit(s,"PUBLIC: "+p.name+" authorized treasury"+std::to_string(org.id)+" grant"+std::to_string(c.amount)+" to "+person(s,c.target).name,{p.id,c.target},true);}
void goal(State&s,const Command&c){auto&p=person(s,c.actor);require(p.body.health>0,"Actor health exhausted");require(!c.text.empty(),"Goal cannot be empty");p.goal=c.text;emit(s,p.name+" chose a new goal",{p.id});}
void talk(State&s,const Command&c){auto&p=person(s,c.actor);idle(p);auto&q=person(s,c.target);require(q.id!=p.id&&co_located(s,p.id,q.id),"Conversation needs another person present");idle(q);require(s.requests.size()<2000,"Request capacity");for(auto&r:s.requests)require(r.status!=0||r.from!=p.id||r.to!=q.id,"Invitation already pending");s.requests.push_back({s.next_request++,p.id,q.id,0});emit(s,p.name+" invited "+q.name+" to exchange information; awaiting consent",{p.id,q.id});}
void accept(State&s,const Command&c){auto&p=person(s,c.actor);idle(p);auto i=std::find_if(s.requests.begin(),s.requests.end(),[&](const Request&r){return r.id==c.target;});require(i!=s.requests.end()&&i->status==0&&i->to==p.id,"No pending invitation addressed to actor");auto&q=person(s,i->from);idle(q);require(co_located(s,p.id,q.id),"Inviter is no longer present");i->status=1;double practice=std::min(p.experience.communication,q.experience.communication);double duration=practice>=4?1:2;start(s,p,ActivityKind::Talk,q.id,duration,i->id);start(s,q,ActivityKind::Talk,p.id,duration,i->id);emit(s,p.name+" accepted conversation with "+q.name,{p.id,q.id});}
void study(State&s,const Command&c){auto&p=person(s,c.actor);idle(p);require(location(s,p.location).kind==SiteKind::Court,"Public records are at court");start(s,p,ActivityKind::Study,p.location,2);}
static void share(State&s,Person&to,const Person&from,const std::vector<Fact>&facts){int count=0;for(auto&f:facts){if(std::none_of(to.knowledge.begin(),to.knowledge.end(),[&](const Fact&known){return known.event==f.event;})){auto copy=f;copy.source=from.id;copy.received=s.tick;to.knowledge.push_back(copy);if(++count==3)break;}}}
void advance(State&s,Person&p){auto&a=p.activity;if(a.kind==ActivityKind::Study){if(p.body.health<=0){cancel_activity(s,p.id,"health exhausted");return;}a.progress+=1;if(a.progress<a.required)return;int n=0;for(auto&e:s.events)if(e.public_notice&&std::none_of(p.knowledge.begin(),p.knowledge.end(),[&](const Fact&f){return f.event==e.id;})){p.knowledge.push_back({e.id,e.text,1,e.tick,s.tick});if(++n==3)break;}p.activity={};emit(s,p.name+" read public records",{p.id});return;}
 if(p.id>a.target)return;auto&q=person(s,a.target);if(p.body.health<=0||q.body.health<=0){cancel_activity(s,p.id,"participant health exhausted");return;}
 ++p.experience.communication;++q.experience.communication;a.progress+=1;q.activity.progress+=1;if(a.progress<a.required)return;
 int request=a.option;auto pk=p.knowledge,qk=q.knowledge;share(s,p,q,qk);share(s,q,p,pk);p.relations[q.id]=std::min(100,p.relations[q.id]+1);q.relations[p.id]=std::min(100,q.relations[p.id]+1);p.activity={};q.activity={};for(auto&r:s.requests)if(r.id==request)r.status=2;emit(s,p.name+" and "+q.name+" exchanged up to3 known facts each; relation+1",{p.id,q.id});
}
}

namespace pe::civic {
void dismiss(State& s,const Command& c){auto& p=person(s,c.actor);idle(p);require(p.id==1,"Only King may dismiss treasury office");require(s.government.office.holder!=0,"Office already vacant");Id former=s.government.office.holder;s.government.office={0,false};for(auto& proposal:s.proposals)if(proposal.kind==ProposalKind::Appointment&&proposal.status==ContractStatus::Pending)proposal.status=ContractStatus::Cancelled;emit(s,"PUBLIC: King dismissed treasury holder; public property unchanged",{1,former},true);}
void announce(State& s,const Command& c){auto& p=person(s,c.actor);idle(p);require((p.id==1||p.id==institution(s,treasury_for_location(s,p.location)).office.holder)&&location(s,p.location).kind==SiteKind::Court,"Only King/office holder at court may announce");require(!c.text.empty(),"Announcement cannot be empty");emit(s,"PUBLIC: "+p.name+" announced: "+c.text,{p.id},true);}
void invitation(State& s,const Command& c){auto& p=person(s,c.actor);idle(p);auto i=std::find_if(s.requests.begin(),s.requests.end(),[&](const Request& r){return r.id==c.target;});require(i!=s.requests.end()&&i->status==0,"Invitation no longer pending");require((c.option==0&&i->to==p.id)||(c.option==1&&i->from==p.id),"Only recipient declines0 or inviter withdraws1");i->status=3;emit(s,p.name+" closed invitation#"+std::to_string(i->id),{i->from,i->to});}
void inspect(State& s,const Command& c){auto& p=person(s,c.actor);idle(p);observe(s,p.id);}
}

